package com.rgapro1.ocaso;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.hardware.biometrics.BiometricPrompt;
import android.os.Build;
import android.os.Bundle;
import android.text.InputType;
import android.util.Base64;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

public class MainActivity extends Activity {
    private static final int NAVY=Color.rgb(20,55,100), BLUE=Color.rgb(11,114,231), BG=Color.rgb(245,247,250), TEXT=Color.rgb(25,35,50), MUTED=Color.rgb(95,105,120);
    private static final int PBKDF2_ITERATIONS=120000;
    private SharedPreferences prefs; private LinearLayout content; private boolean authenticated=false; private boolean authScreen=false;
    private final Executor executor=Executors.newSingleThreadExecutor();
    private final ArrayList<String> clients=new ArrayList<>(), documents=new ArrayList<>();
    private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}

    @Override protected void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("rgapro_local",Context.MODE_PRIVATE);if(hasPin())showAccessScreen();else showCreatePin();}
    @Override protected void onResume(){super.onResume();if(prefs!=null&&hasPin()&&!authenticated&&!authScreen)showAccessScreen();}
    private boolean hasPin(){return prefs.contains("pin_hash")&&prefs.contains("pin_salt");}
    private EditText pinInput(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}

    private void showCreatePin(){authScreen=true;final EditText a=pinInput("Nueva clave de 6 dígitos"),b=pinInput("Repite la clave");LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(22),0,dp(22),0);box.addView(a,new LinearLayout.LayoutParams(-1,dp(52)));box.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));
        AlertDialog d=new AlertDialog.Builder(this).setTitle("Protege RgaPro").setMessage("Crea una clave de acceso. También podrás entrar con la biometría del dispositivo.").setView(box).setCancelable(false).setPositiveButton("Activar seguridad",null).create();
        d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String p=a.getText().toString();if(!p.matches("\\d{6}")){a.setError("Usa exactamente 6 dígitos");return;}if(!p.equals(b.getText().toString())){b.setError("Las claves no coinciden");return;}savePin(p);prefs.edit().putBoolean("biometric",true).apply();d.dismiss();authScreen=false;authenticated=true;loadData();buildHome();Toast.makeText(this,"Seguridad activada",Toast.LENGTH_SHORT).show();}));d.setOnDismissListener(x->authScreen=false);d.show();}

    private void savePin(String pin){try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);byte[] hash=derive(pin,salt);prefs.edit().putString("pin_salt",Base64.encodeToString(salt,Base64.NO_WRAP)).putString("pin_hash",Base64.encodeToString(hash,Base64.NO_WRAP)).apply();}catch(Exception e){throw new IllegalStateException(e);}}
    private boolean verifyPin(String pin){try{byte[] s=Base64.decode(prefs.getString("pin_salt",""),Base64.NO_WRAP);byte[] h=Base64.decode(prefs.getString("pin_hash",""),Base64.NO_WRAP);return MessageDigest.isEqual(h,derive(pin,s));}catch(Exception e){return false;}}
    private byte[] derive(String pin,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(pin.toCharArray(),salt,PBKDF2_ITERATIONS,256);try{SecretKeyFactory f;try{f=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");}catch(Exception e){f=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");}return f.generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}

    private void showAccessScreen(){authScreen=true;LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(dp(28),dp(28),dp(28),dp(28));r.setBackgroundColor(BG);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_rgapro);logo.setContentDescription("Logotipo RgaPro");r.addView(logo,new LinearLayout.LayoutParams(dp(90),dp(90)));TextView t=label("RgaPro",28,NAVY,true);t.setGravity(Gravity.CENTER);r.addView(t,new LinearLayout.LayoutParams(-1,dp(55)));TextView s=label("Acceso protegido",16,MUTED,false);s.setGravity(Gravity.CENTER);r.addView(s,new LinearLayout.LayoutParams(-1,dp(40)));
        Button p=primaryButton("Introducir clave");p.setOnClickListener(v->showPinLogin());LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(52));pp.topMargin=dp(18);r.addView(p,pp);
        if(prefs.getBoolean("biometric",true)&&Build.VERSION.SDK_INT>=28){Button bio=button("Usar biometría");bio.setOnClickListener(v->authenticateBiometric());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(52));bp.topMargin=dp(10);r.addView(bio,bp);}
        TextView i=label("La clave se guarda como un hash derivado con salt; nunca en texto plano.",12,MUTED,false);i.setGravity(Gravity.CENTER);i.setPadding(dp(8),dp(18),dp(8),0);r.addView(i,new LinearLayout.LayoutParams(-1,dp(65)));setContentView(r);}

    private void showPinLogin(){final EditText e=pinInput("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("Desbloquear RgaPro").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(verifyPin(e.getText().toString())){d.dismiss();authenticated=true;authScreen=false;loadData();buildHome();}else e.setError("Clave incorrecta");}));d.show();}

    private void authenticateBiometric(){if(Build.VERSION.SDK_INT<28){showPinLogin();return;}BiometricPrompt.Builder b=new BiometricPrompt.Builder(this).setTitle("Acceso a RgaPro").setSubtitle("Confirma tu identidad").setDescription("Usa la biometría configurada en este dispositivo.");if(Build.VERSION.SDK_INT>=29)b.setDeviceCredentialAllowed(false);else b.setNegativeButton("Usar clave",executor,(d,w)->runOnUiThread(this::showPinLogin));BiometricPrompt prompt=b.build();prompt.authenticate(null,executor,new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult result){runOnUiThread(()->{authenticated=true;authScreen=false;loadData();buildHome();});}@Override public void onAuthenticationError(int code,CharSequence msg){runOnUiThread(()->Toast.makeText(MainActivity.this,"Biometría: "+msg,Toast.LENGTH_SHORT).show());}});}

    private void loadData(){clients.clear();documents.clear();Set<String> c=prefs.getStringSet("clients",null),d=prefs.getStringSet("documents",null);if(c!=null)clients.addAll(c);if(d!=null)documents.addAll(d);if(clients.isEmpty()){clients.add("Cliente de demostración");saveClients();}if(documents.isEmpty()){documents.add("Documento de demostración.pdf");saveDocuments();}}
    private void saveClients(){prefs.edit().putStringSet("clients",new HashSet<>(clients)).apply();}private void saveDocuments(){prefs.edit().putStringSet("documents",new HashSet<>(documents)).apply();}
    private TextView label(String s,float z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER_VERTICAL);v.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);return v;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setTextColor(TEXT);b.setAllCaps(false);b.setMinHeight(0);b.setPadding(dp(16),0,dp(16),0);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(12));g.setStroke(dp(1),Color.rgb(220,225,232));b.setBackground(g);return b;}
    private Button primaryButton(String s){Button b=button(s);b.setTextColor(Color.WHITE);GradientDrawable g=new GradientDrawable();g.setColor(BLUE);g.setCornerRadius(dp(12));b.setBackground(g);return b;}

    private LinearLayout page(String title,String sub){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(10),0,dp(16),0);bar.setBackgroundColor(NAVY);Button back=new Button(this);back.setText("‹");back.setTextColor(Color.WHITE);back.setTextSize(30);back.setAllCaps(false);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->buildHome());bar.addView(back,new LinearLayout.LayoutParams(dp(48),dp(64)));bar.addView(label(title,21,Color.WHITE,true),new LinearLayout.LayoutParams(0,dp(64),1));root.addView(bar);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(18),dp(18),dp(18),dp(28));if(sub!=null){TextView x=label(sub,15,MUTED,false);x.setPadding(dp(4),0,dp(4),dp(14));content.addView(x,new LinearLayout.LayoutParams(-1,dp(48)));}ScrollView sc=new ScrollView(this);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);return root;}

    private void buildHome(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(16),dp(8),dp(18),dp(8));h.setBackgroundColor(NAVY);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_rgapro);logo.setContentDescription("Logotipo RgaPro");h.addView(logo,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=label("RgaPro",25,Color.WHITE,true);title.setPadding(dp(10),0,0,0);h.addView(title,new LinearLayout.LayoutParams(0,dp(64),1));root.addView(h);ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(22),dp(20),dp(30));TextView w=label("Bienvenido a RgaPro",25,TEXT,true);w.setGravity(Gravity.CENTER);body.addView(w,new LinearLayout.LayoutParams(-1,dp(58)));TextView ds=label("Gestión profesional, organizada y sencilla.",16,MUTED,false);ds.setGravity(Gravity.CENTER);body.addView(ds,new LinearLayout.LayoutParams(-1,dp(45)));addHomeButton(body,"CLIENTES","Gestiona tus clientes",v->buildClients());addHomeButton(body,"DOCUMENTOS","Consulta y organiza documentos",v->buildDocuments());addHomeButton(body,"CONFIGURACIÓN","Seguridad y preferencias",v->buildSettings());TextView ver=label("RgaPro V1.2 · Acceso protegido",13,Color.GRAY,false);ver.setGravity(Gravity.CENTER);LinearLayout.LayoutParams vp=new LinearLayout.LayoutParams(-1,dp(40));vp.topMargin=dp(22);body.addView(ver,vp);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void addHomeButton(LinearLayout p,String t,String st,View.OnClickListener l){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(10),dp(18),dp(10));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(14));g.setStroke(dp(1),Color.rgb(225,229,235));c.setBackground(g);c.setOnClickListener(l);c.addView(label(t,17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(28)));c.addView(label(st,13,MUTED,false),new LinearLayout.LayoutParams(-1,dp(24)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(72));cp.topMargin=dp(12);p.addView(c,cp);}

    private void buildClients(){page("Clientes","Clientes guardados únicamente en este dispositivo.");Button add=primaryButton("+ Añadir cliente");add.setOnClickListener(v->showAddClient());content.addView(add,new LinearLayout.LayoutParams(-1,dp(50)));addListHeader("Tus clientes");renderClients();}
    private void renderClients(){while(content.getChildCount()>2)content.removeViewAt(2);for(int i=0;i<clients.size();i++){final int n=i;LinearLayout r=listRow(clients.get(i),"Cliente local");r.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(clients.get(n)).setItems(new String[]{"Ver ficha","Eliminar"},(d,w)->{if(w==0)Toast.makeText(this,"Ficha local de "+clients.get(n),Toast.LENGTH_SHORT).show();else{clients.remove(n);saveClients();buildClients();}}).show());content.addView(r);}}
    private void showAddClient(){EditText e=new EditText(this);e.setHint("Nombre del cliente");e.setSingleLine(true);AlertDialog d=new AlertDialog.Builder(this).setTitle("Nuevo cliente").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String n=e.getText().toString().trim();if(n.isEmpty()){e.setError("Introduce un nombre");return;}clients.add(n);saveClients();d.dismiss();buildClients();}));d.show();}

    private void buildDocuments(){page("Documentos","Organización local de documentos.");Button add=primaryButton("+ Añadir documento");add.setOnClickListener(v->showAddDocument());content.addView(add,new LinearLayout.LayoutParams(-1,dp(50)));addListHeader("Documentos recientes");renderDocuments();}
    private void renderDocuments(){while(content.getChildCount()>2)content.removeViewAt(2);for(int i=0;i<documents.size();i++){final int n=i;LinearLayout r=listRow(documents.get(i),"Documento local");r.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(documents.get(n)).setItems(new String[]{"Abrir ficha","Eliminar"},(d,w)->{if(w==0)Toast.makeText(this,"Documento preparado para integración",Toast.LENGTH_SHORT).show();else{documents.remove(n);saveDocuments();buildDocuments();}}).show());content.addView(r);}}
    private void showAddDocument(){EditText e=new EditText(this);e.setHint("Nombre del documento");e.setSingleLine(true);new AlertDialog.Builder(this).setTitle("Nuevo documento").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty()){documents.add(n);saveDocuments();buildDocuments();}}).show();}
    private LinearLayout listRow(String t,String st){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(16),dp(8),dp(16),dp(8));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(12));g.setStroke(dp(1),Color.rgb(225,229,235));r.setBackground(g);r.addView(label(t,16,TEXT,true),new LinearLayout.LayoutParams(-1,dp(30)));r.addView(label(st,12,MUTED,false),new LinearLayout.LayoutParams(-1,dp(22)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(64));lp.topMargin=dp(10);r.setLayoutParams(lp);return r;}
    private void addListHeader(String t){TextView h=label(t,17,TEXT,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.topMargin=dp(14);content.addView(h,lp);}

    private void buildSettings(){page("Configuración","Seguridad y preferencias locales.");content.addView(label("SEGURIDAD",13,BLUE,true),new LinearLayout.LayoutParams(-1,dp(36)));Button bio=button(prefs.getBoolean("biometric",true)?"✓ Biometría activada":"Activar biometría");bio.setOnClickListener(v->{prefs.edit().putBoolean("biometric",!prefs.getBoolean("biometric",true)).apply();buildSettings();});content.addView(bio,new LinearLayout.LayoutParams(-1,dp(52)));Button cp=button("Cambiar clave de acceso");cp.setOnClickListener(v->changePin());content.addView(cp,new LinearLayout.LayoutParams(-1,dp(52)));TextView n=label("La clave usa PBKDF2 con salt aleatorio y no se almacena en texto plano. La biometría usa el sistema seguro del dispositivo.",13,MUTED,false);n.setPadding(dp(4),dp(8),dp(4),dp(14));content.addView(n,new LinearLayout.LayoutParams(-1,dp(76)));Button clear=button("Borrar datos de demostración");clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Borrar datos").setMessage("Se eliminarán los clientes y documentos locales.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar",(d,w)->{clients.clear();documents.clear();prefs.edit().clear().apply();authenticated=false;showCreatePin();}).show());content.addView(clear,new LinearLayout.LayoutParams(-1,dp(52)));}
    private void changePin(){final EditText o=pinInput("Clave actual"),n=pinInput("Nueva clave de 6 dígitos"),c=pinInput("Repite la nueva clave");LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(22),0,dp(22),0);box.addView(o,new LinearLayout.LayoutParams(-1,dp(52)));box.addView(n,new LinearLayout.LayoutParams(-1,dp(52)));box.addView(c,new LinearLayout.LayoutParams(-1,dp(52)));AlertDialog d=new AlertDialog.Builder(this).setTitle("Cambiar clave").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(!verifyPin(o.getText().toString())){o.setError("Clave actual incorrecta");return;}if(!n.getText().toString().matches("\\d{6}")){n.setError("Usa 6 dígitos");return;}if(!n.getText().toString().equals(c.getText().toString())){c.setError("No coincide");return;}savePin(n.getText().toString());d.dismiss();Toast.makeText(this,"Clave actualizada",Toast.LENGTH_SHORT).show();}));d.show();}
}